  TerminalLogsCompanion copyWith({
    Value<int>? id,
    Value<String?>? projectId,
    Value<String?>? serverId,
    Value<String?>? serverLabel,
    Value<String>? message,
    Value<String>? renderedLine,
    Value<String>? source,
    Value<String?>? taskType,
    Value<DateTime>? createdAt,
  }) {
    return TerminalLogsCompanion(
      id: id ?? this.id,
      projectId: projectId ?? this.projectId,
      serverId: serverId ?? this.serverId,
      serverLabel: serverLabel ?? this.serverLabel,
      message: message ?? this.message,
      renderedLine: renderedLine ?? this.renderedLine,
      source: source ?? this.source,
      taskType: taskType ?? this.taskType,
      createdAt: createdAt ?? this.createdAt,
    );
  }

  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (id.present) {
      map['id'] = Variable<int>(id.value);
    }
    if (projectId.present) {
      map['project_id'] = Variable<String>(projectId.value);
    }
    if (serverId.present) {
      map['server_id'] = Variable<String>(serverId.value);
    }
    if (serverLabel.present) {
      map['server_label'] = Variable<String>(serverLabel.value);
    }
    if (message.present) {
      map['message'] = Variable<String>(message.value);
    }
    if (renderedLine.present) {
      map['rendered_line'] = Variable<String>(renderedLine.value);
    }
    if (source.present) {
      map['source'] = Variable<String>(source.value);
    }
    if (taskType.present) {
      map['task_type'] = Variable<String>(taskType.value);
    }
    if (createdAt.present) {
      map['created_at'] = Variable<DateTime>(createdAt.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('TerminalLogsCompanion(')
          ..write('id: $id, ')
          ..write('projectId: $projectId, ')
          ..write('serverId: $serverId, ')
          ..write('serverLabel: $serverLabel, ')
          ..write('message: $message, ')
          ..write('renderedLine: $renderedLine, ')
          ..write('source: $source, ')
          ..write('taskType: $taskType, ')
          ..write('createdAt: $createdAt')
          ..write(')'))
        .toString();
  }
