      appDisconnected: attachedDatabase.typeMapping.read(
        DriftSqlType.bool,
        data['${effectivePrefix}app_disconnected'],
      )!,
      injectPostgresEnv: attachedDatabase.typeMapping.read(
        DriftSqlType.bool,
        data['${effectivePrefix}inject_postgres_env'],
      )!,
      sqliteStorageEnabled: attachedDatabase.typeMapping.read(
        DriftSqlType.bool,
        data['${effectivePrefix}sqlite_storage_enabled'],
      )!,
      sqliteVolumeName: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}sqlite_volume_name'],
      ),
      sqliteMountPath: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}sqlite_mount_path'],
      ),
      sqliteFileName: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}sqlite_file_name'],
      ),
      isActive: attachedDatabase.typeMapping.read(
        DriftSqlType.bool,
        data['${effectivePrefix}is_active'],
      )!,
      createdAt: attachedDatabase.typeMapping.read(
        DriftSqlType.dateTime,
        data['${effectivePrefix}created_at'],
      )!,
      updatedAt: attachedDatabase.typeMapping.read(
        DriftSqlType.dateTime,
        data['${effectivePrefix}updated_at'],
      )!,
    );
  }

  @override
  $ProjectsTable createAlias(String alias) {
    return $ProjectsTable(attachedDatabase, alias);
  }
}

class ProjectRow extends DataClass implements Insertable<ProjectRow> {
  /// The project's id.
  final String id;

  /// The server it is deployed to. Null while a project exists but has no
  /// server yet, which is a real state during onboarding.
  final String? serverId;

  /// What the user calls it. Also what its slug is derived from.
  final String name;

  /// What kind of project it is.
  final String type;

  /// The repository's git URL.
  final String gitUrl;

  /// The domain the app is served on, lower-cased.
  ///
  /// For a redirect routing mode this is stored as the apex, with any leading
  /// `www.` stripped -- the redirect needs a fixed point to redirect to.
  final String primaryDomain;

  /// `single_host`, `redirect_www_to_apex`, or `redirect_apex_to_www`.
  final String domainRoutingMode;

  /// The GitHub repository as `owner/name`.
  final String? repositoryFullName;

  /// The subdirectory within the repository to build from, for a monorepo.
  /// Null means the repository root.
  final String? appSubdirectory;

  /// The branch deployed. `main` by default.
  final String deployBranch;

  /// The port the app listens on. 3000 by default, and anything outside
  /// 1-65535 is normalized back to it.
  final int appPort;

  /// Whether to check the public URL after a deploy. On by default.
  final bool publicHealthCheckEnabled;

  /// The path that check requests. Always starts with `/`; `/` by default, so
  /// an app with no health endpoint uses its home page.
  final String publicHealthCheckPath;

  /// The commit of the last successful deploy.
  final String? lastDeployCommit;

  /// When that deploy happened.
  final DateTime? lastDeployedAt;

  /// The build command. Blank means "let Railpack detect it"; the Node default
  /// is pre-filled here for projects created before a provider was recorded.
  final String railpackBuildCommand;

  /// The start command, with the same blank-means-detect rule.
  final String railpackRunCommand;

  /// The chosen Railpack provider, or null for auto-detection. An
  /// unrecognised value reads back as null -- see `normalizeRailpackProvider`.
  final String? railpackProvider;

  /// `auto` or `runtime`, deciding how Node is provided in the image.
  final String railpackNodeMode;

  /// `http` or `dns`, deciding how the TLS certificate is proven. `http` by
  /// default, since it needs no provider credentials.
  final String tlsChallengeMode;

  /// The DNS provider for a `dns` challenge, from a closed set.
  final String? tlsDnsProvider;

  /// That provider's credentials as JSON. Cleared when the challenge mode
  /// moves away from `dns`, rather than left behind unused.
  final String? tlsDnsConfigJson;

  /// Whether the app has been disconnected from its server.
  final bool appDisconnected;

  /// Whether managed PostgreSQL credentials are wired into this project.
  final bool injectPostgresEnv;

  /// Whether the app has a SQLite volume mounted.
  final bool sqliteStorageEnabled;

  /// The Docker volume holding it. Null when the value would not be safe as a
  /// volume name -- the repository normalizes rather than storing it raw.
  final String? sqliteVolumeName;

  /// Where it mounts in the container, absolute and free of `.` and `..`.
  final String? sqliteMountPath;

  /// The database filename inside that mount.
  final String? sqliteFileName;

  /// Whether this is the selected project on its server. At most one is, per
  /// server; `ProjectRepository` maintains that.
  final bool isActive;

  /// When the project was created.
  final DateTime createdAt;

  /// When the row last changed.
  final DateTime updatedAt;
  const ProjectRow({
    required this.id,
    this.serverId,
    required this.name,
    required this.type,
    required this.gitUrl,
    required this.primaryDomain,
    required this.domainRoutingMode,
    this.repositoryFullName,
    this.appSubdirectory,
    required this.deployBranch,
    required this.appPort,
    required this.publicHealthCheckEnabled,
    required this.publicHealthCheckPath,
    this.lastDeployCommit,
    this.lastDeployedAt,
    required this.railpackBuildCommand,
    required this.railpackRunCommand,
    this.railpackProvider,
    required this.railpackNodeMode,
    required this.tlsChallengeMode,
    this.tlsDnsProvider,
    this.tlsDnsConfigJson,
    required this.appDisconnected,
    required this.injectPostgresEnv,
    required this.sqliteStorageEnabled,
    this.sqliteVolumeName,
    this.sqliteMountPath,
    this.sqliteFileName,
    required this.isActive,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    if (!nullToAbsent || serverId != null) {
      map['server_id'] = Variable<String>(serverId);
    }
    map['name'] = Variable<String>(name);
    map['type'] = Variable<String>(type);
    map['git_url'] = Variable<String>(gitUrl);
    map['primary_domain'] = Variable<String>(primaryDomain);
    map['domain_routing_mode'] = Variable<String>(domainRoutingMode);
    if (!nullToAbsent || repositoryFullName != null) {
      map['repository_full_name'] = Variable<String>(repositoryFullName);
    }
    if (!nullToAbsent || appSubdirectory != null) {
      map['app_subdirectory'] = Variable<String>(appSubdirectory);
    }
    map['deploy_branch'] = Variable<String>(deployBranch);
    map['app_port'] = Variable<int>(appPort);
    map['public_health_check_enabled'] = Variable<bool>(
      publicHealthCheckEnabled,
    );
    map['public_health_check_path'] = Variable<String>(publicHealthCheckPath);
    if (!nullToAbsent || lastDeployCommit != null) {
      map['last_deploy_commit'] = Variable<String>(lastDeployCommit);
    }
    if (!nullToAbsent || lastDeployedAt != null) {
      map['last_deployed_at'] = Variable<DateTime>(lastDeployedAt);
    }
    map['railpack_build_command'] = Variable<String>(railpackBuildCommand);
    map['railpack_run_command'] = Variable<String>(railpackRunCommand);
    if (!nullToAbsent || railpackProvider != null) {
      map['railpack_provider'] = Variable<String>(railpackProvider);
    }
    map['railpack_node_mode'] = Variable<String>(railpackNodeMode);
    map['tls_challenge_mode'] = Variable<String>(tlsChallengeMode);
    if (!nullToAbsent || tlsDnsProvider != null) {
      map['tls_dns_provider'] = Variable<String>(tlsDnsProvider);
    }
    if (!nullToAbsent || tlsDnsConfigJson != null) {
      map['tls_dns_config_json'] = Variable<String>(tlsDnsConfigJson);
    }
    map['app_disconnected'] = Variable<bool>(appDisconnected);
    map['inject_postgres_env'] = Variable<bool>(injectPostgresEnv);
    map['sqlite_storage_enabled'] = Variable<bool>(sqliteStorageEnabled);
    if (!nullToAbsent || sqliteVolumeName != null) {
      map['sqlite_volume_name'] = Variable<String>(sqliteVolumeName);
    }
    if (!nullToAbsent || sqliteMountPath != null) {
      map['sqlite_mount_path'] = Variable<String>(sqliteMountPath);
    }
    if (!nullToAbsent || sqliteFileName != null) {
      map['sqlite_file_name'] = Variable<String>(sqliteFileName);
    }
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  ProjectsCompanion toCompanion(bool nullToAbsent) {
    return ProjectsCompanion(
      id: Value(id),
