          : Value(tlsDnsConfigJson),
      appDisconnected: Value(appDisconnected),
      injectPostgresEnv: Value(injectPostgresEnv),
      sqliteStorageEnabled: Value(sqliteStorageEnabled),
      sqliteVolumeName: sqliteVolumeName == null && nullToAbsent
