    map['memory_mb'] = Variable<int>(memoryMb);
    map['disk_mb'] = Variable<int>(diskMb);
    if (!nullToAbsent || databaseUser != null) {
      map['database_user'] = Variable<String>(databaseUser);
    }
    if (!nullToAbsent || databaseName != null) {
      map['database_name'] = Variable<String>(databaseName);
    }
    if (!nullToAbsent || databasePassword != null) {
      map['database_password'] = Variable<String>(databasePassword);
    }
    if (!nullToAbsent || databaseEngine != null) {
